python - <<'PY'
from PIL import Image
import numpy as np
im=np.array(Image.open('/app/output/practice_clear3_practice_cam.png').convert('L'))
mask=im<80
h,w=mask.shape
# connected components
from collections import deque
seen=np.zeros_like(mask,bool)
for y in range(h):
 for x in range(w):
  if mask[y,x] and not seen[y,x]:
   q=deque([(y,x)]);seen[y,x]=1;xs=[];ys=[]
   while q:
    yy,xx=q.popleft();xs.append(xx);ys.append(yy)
    for dy in (-1,0,1):
     for dx in (-1,0,1):
      Y,X=yy+dy,xx+dx
      if 0<=Y<h and 0<=X<w and mask[Y,X] and not seen[Y,X]:seen[Y,X]=1;q.append((Y,X))
   if len(xs)>30: print(len(xs),(min(xs),min(ys),max(xs),max(ys)), 'max_row_width',max(mask[yy].sum() for yy in range(min(ys),max(ys)+1)))
# row widths center approx for stroke bands
for xlo,xhi in [(90,170),(220,280),(300,375)]:
 vals=[]
 for y in range(320,640):
  n=mask[y,xlo:xhi].sum()
  if n: vals.append(n)
 print((xlo,xhi),'widths range',min(vals),max(vals),'median',np.median(vals))
